<?php require '../includes/functions.php';require_login();$id=intval($_GET['id']??0);$st=$pdo->prepare('SELECT r.*,u.name,u.email FROM reports r JOIN users u ON u.id=r.user_id WHERE r.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r||($r['status']==='hidden'&&user()['role']!=='admin'))die('Reporte no disponible');if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['comment'])){check_csrf();$c=trim($_POST['comment']);if($c){$pdo->prepare('INSERT INTO comments(report_id,user_id,body) VALUES(?,?,?)')->execute([$id,user()['id'],$c]);flash('Comentario publicado.');}header('Location: '.url('reports/view.php?id='.$id));exit;}$cs=$pdo->prepare('SELECT c.*,u.name FROM comments c JOIN users u ON u.id=c.user_id WHERE report_id=? ORDER BY c.created_at ASC');$cs->execute([$id]);$comments=$cs->fetchAll();$ms=$pdo->prepare("SELECT r.*,u.name FROM reports r JOIN users u ON u.id=r.user_id WHERE r.status='open' AND r.id<>? ORDER BY r.created_at DESC LIMIT 100");$ms->execute([$id]);$matches=[];$similar=[];foreach($ms as $m){$d=match_details($r,$m);if($m['type']!==$r['type']){if(($d['eligible']??false) && $d['total']>=30)$matches[]=[$m,$d];}else{if(($d['eligible']??false) && $d['total']>=35)$similar[]=[$m,$d];}}usort($matches,fn($a,$b)=>$b[1]['total']<=>$a[1]['total']);usort($similar,fn($a,$b)=>$b[1]['total']<=>$a[1]['total']);$matches=array_slice($matches,0,5);$similar=array_slice($similar,0,3);$title=$r['title'];require '../includes/header.php';?>
<main class="dashboard"><a class="muted" href="<?=url('app.php')?>">← Volver a la comunidad</a><div class="report-layout" style="margin-top:18px"><section class="panel"><?php if($r['image']&&!$r['is_sensitive']):?><img class="detail-img" src="<?=url('uploads/'.e($r['image']))?>"><?php elseif($r['is_sensitive']):?><div class="empty"><div class="placeholder">🪪</div><h3>Imagen protegida</h3><p>Este reporte fue marcado como sensible.</p></div><?php endif;?><div style="margin-top:20px"><span class="badge <?=e($r['type'])?>"><?=$r['type']==='lost'?'OBJETO PERDIDO':'OBJETO ENCONTRADO'?></span><?php if($r['status']==='resolved'):?><span class="badge resolved"><?=resolved_label($r)?></span><?php endif;?><h1><?=e($r['title'])?></h1><p><?=nl2br(e($r['description']))?></p><p class="muted">📍 <?=e($r['location'])?> · 📅 <?=date('d/m/Y',strtotime($r['event_date']))?> · 🎨 <?=e($r['color']?:'No indicado')?></p><div class="author"><span class="avatar"><?=e(mb_substr($r['name'],0,1))?></span><div><b><?=e($r['name'])?></b><br><span class="muted">Publicado <?=timeago($r['created_at'])?></span></div></div>
<?php if($r['ai_embedding']):?><div class="ai-box"><b>✨ Fotografía analizada por Encuéntralo</b><p>La imagen fue procesada correctamente y sus características visuales se están comparando con otros reportes. Las etiquetas técnicas del modelo se mantienen internas para no confundir al usuario.</p></div><?php endif;?>
<?php if((int)$r['user_id']===(int)user()['id']):?><div class="owner-box"><div><b>Esta publicación es tuya</b><p class="small muted">Solo tú puedes cerrar, reactivar o eliminar este reporte.</p></div><div class="owner-actions"><?php if($r['status']==='open'):?><form method="post" action="<?=url('reports/action.php')?>"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="resolve"><button class="btn success"><?=$r['type']==='lost'?'✓ Ya lo encontré':'✓ Ya fue entregado'?></button></form><?php else:?><form method="post" action="<?=url('reports/action.php')?>"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="reopen"><button class="btn">Reactivar reporte</button></form><?php endif;?><form method="post" action="<?=url('reports/action.php')?>" onsubmit="return confirm('¿Seguro que deseas eliminar esta publicación? Esta acción no se puede deshacer.')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="delete"><button class="btn danger-btn">Eliminar</button></form></div></div><?php endif;?></div>
<div class="comments"><h3>Comentarios (<?=count($comments)?>)</h3><?php foreach($comments as $c):?><div class="comment"><b><?=e($c['name'])?></b> <span class="muted small"><?=timeago($c['created_at'])?></span><p><?=nl2br(e($c['body']))?></p></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>¿Tienes información que pueda ayudar?</label><textarea name="comment" rows="3" required placeholder="Escribe un comentario..."></textarea><button class="btn primary" style="margin-top:10px">Comentar</button></form></div></section>
<aside><div class="panel"><h3>Detalles del reporte</h3><p><b>Categoría</b><br><span class="muted"><?=e($r['category'])?></span></p><p><b>Estado</b><br><span class="muted"><?=$r['status']==='open'?'Activo':($r['status']==='resolved'?mb_convert_case(resolved_label($r),MB_CASE_TITLE,'UTF-8'):'Oculto')?></span></p><p><b>Reporte #</b><br><span class="muted"><?=intval($r['id'])?></span></p></div>
<div class="panel ai-matches" style="margin-top:18px"><div class="ai-heading"><span class="ai-orb">AI</span><div><h3>Coincidencias inteligentes</h3><p class="small muted">La IA reconoce primero qué tipo de objeto aparece en la fotografía y luego compara su apariencia. La categoría escrita por el usuario no decide la coincidencia.</p></div></div><?php foreach($matches as [$m,$d]):?><a class="match-card" href="<?=url('reports/view.php?id='.$m['id'])?>"><div class="match-image"><?php if($m['image']&&!$m['is_sensitive']):?><img src="<?=url('uploads/'.e($m['image']))?>"><?php else:?><div class="placeholder small-ph"><?=$m['is_sensitive']?'🪪':'🎒'?></div><?php endif;?><span class="match-score"><?=$d['total']?>%</span></div><div class="match-info"><b><?=e($m['title'])?></b><p class="small muted">📍 <?=e($m['location'])?> · <?=date('d/m/Y',strtotime($m['event_date']))?></p><?php if($d['image']!==null):?><div class="metric"><span>Coincidencia estimada por IA</span><b><?=$d['image']?>%</b></div><?php endif;?><div class="progress"><i style="width:<?=$d['total']?>%"></i></div><div class="reason-chips"><?php foreach(array_slice($d['reasons'],0,3) as $reason):?><span><?=e($reason)?></span><?php endforeach;?></div><p class="review-hint">Ver y comparar este reporte →</p></div></a><?php endforeach;?><?php if(!$matches):?><div class="no-match"><b>Todavía no hay un reporte encontrado con suficiente similitud.</b><p class="muted small">Cuando aparezca un reporte del tipo contrario, Encuéntralo lo comparará automáticamente. Recuerda: para recuperar un objeto perdido debe existir al menos un reporte marcado como ENCONTRADO.</p></div><?php endif;?><?php if($similar):?><div class="similar-section"><h4>Reportes parecidos en la comunidad</h4><p class="small muted">Estos reportes son del mismo tipo que el tuyo. No representan una recuperación, pero ayudan a detectar publicaciones duplicadas o fotografías muy similares.</p><?php foreach($similar as [$m,$d]):?><a class="match-card" href="<?=url('reports/view.php?id='.$m['id'])?>"><div class="match-image"><?php if($m['image']&&!$m['is_sensitive']):?><img src="<?=url('uploads/'.e($m['image']))?>"><?php endif;?><span class="match-score"><?=$d['total']?>%</span></div><div class="match-info"><b><?=e($m['title'])?></b><p class="small muted">Publicado por <?=e($m['name'])?> · <?=$m['type']==='lost'?'PERDIDO':'ENCONTRADO'?></p><?php if($d['image']!==null):?><div class="metric"><span>Similitud de fotografías</span><b><?=$d['image']?>%</b></div><?php endif;?><p class="review-hint">Revisar publicación →</p></div></a><?php endforeach;?></div><?php endif;?><div class="ai-disclaimer">La coincidencia se calcula principalmente por similitud visual. El porcentaje orienta la revisión, pero no confirma por sí solo que sea el mismo objeto.</div></div></aside></div></main><?php require '../includes/footer.php';?>
